const b=$input.first().json.body;
if(!b || typeof b.text!== 'string' || !b.text.trim() || b.text.length>5000 || typeof b.session_key!=='string' || !/^wa:[0-9]{5,30}:[0-9]{8,20}$/.test(b.session_key)) throw new Error('Solicitud WhatsApp inválida');
return [{json:{text:b.text,session_key:b.session_key}}];

const raw=$input.first().json.output;
if(typeof raw!=='string' || raw.length>10000) throw new Error('Respuesta IA inválida');
let answer;try{answer=JSON.parse(raw.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,''));}catch{throw new Error('La IA no devolvió JSON válido');}
if(!answer || typeof answer.reply!=='string' || !answer.reply.trim() || answer.reply.length>1500) throw new Error('Respuesta vacía o demasiado larga');
const q=answer.qualification||{};
return [{json:{reply:answer.reply.trim(),qualification:{businessFit:q.businessFit===true,commercialIntent:q.commercialIntent===true,interest:typeof q.interest==='string'?q.interest.slice(0,500):'',name:typeof q.name==='string'?q.name.slice(0,200):'',company:typeof q.company==='string'?q.company.slice(0,200):'',handoff:q.handoff===true}}}];
